"""
CLC-LBU Staff Portal — Connecting a PC to a Classroom TV
Interactive step-by-step guide with dropdown navigation.
Self-contained: diagrams are embedded as base64, no external assets needed.
"""
import streamlit as st
import base64

st.set_page_config(page_title="Connect PC to Classroom TV", page_icon="📺", layout="centered")

# ---------------------------------------------------------------
# Embedded diagrams (base64 PNG) — generated once, no external files needed
# ---------------------------------------------------------------
IMAGES = {}
IMAGES["step1_setup.png"] = """"""
IMAGES["step2_connect.png"] = """"""
IMAGES["step3_pin.png"] = """"""
IMAGES["step4_mode.png"] = """"""
IMAGES["step5_disconnect.png"] = """"""
IMAGES["step6_remove_old.png"] = """"""

def img_bytes(name):
    return base64.b64decode(IMAGES[name])

STEPS = [
    {
        "img": "step1_setup.png",
        "title": '1. Check the adapter is ready',
        "desc": 'Each classroom TV has a Microsoft Wireless Display Adapter already connected: the HDMI lead carries the picture and the USB lead powers the adapter. A solid light on the adapter means it\'s ready to receive a connection. Switch the TV to the correct HDMI input if it isn\'t already showing "Ready to connect" or similar.',
    },
    {
        "img": "step2_connect.png",
        "title": '2. Open Connect on your laptop',
        "desc": 'On your Windows laptop, press the Windows key + K, or open the Action Centre (bottom-right of the taskbar) and choose Cast or Connect. A panel opens on the right listing nearby wireless displays — select the one named for that room.',
    },
    {
        "img": "step3_pin.png",
        "title": '3. Enter the PIN (first connection only)',
        "desc": "The first time your laptop connects to a particular room's adapter, the TV displays a short PIN. Type this into the box that appears on your laptop and select Connect. Once paired, most laptops reconnect to that room automatically in future — no PIN needed.",
    },
    {
        "img": "step4_mode.png",
        "title": '4. Choose how the screens work together',
        "desc": "Press Windows key + P at any time to choose a display mode. For teaching to a class, Duplicate is almost always the right choice — it mirrors exactly what's on your laptop screen onto the TV. Extend instead treats the TV as extra desktop space, useful for presenting on the TV while keeping notes private on your own screen.",
    },
    {
        "img": "step5_disconnect.png",
        "title": "5. Disconnect when you're finished",
        "desc": 'Reopen Connect (Windows key + K) and select Disconnect, or simply close your laptop lid / walk out of range. This frees the adapter up for the next person to use.',
    },
    {
        "img": "step6_remove_old.png",
        "title": '6. If an old or renamed version of the adapter is listed',
        "desc": 'Sometimes an adapter shows up under an old, renamed, or duplicate entry — this stops the current one from connecting properly. Go to Settings → Bluetooth & devices → Devices, remove the outdated entry, then use "Add device → Wireless display or dock" to re-pair under its current name.',
    },
]

TROUBLESHOOTING = [
    {
        "title": "If the TV isn't showing up in the list",
        "bullets": ['Confirm Wi-Fi is turned on on your laptop — Airplane Mode blocks the wireless connection.', 'Move closer to the TV and try again.', "Ask another staff member to check the TV is on the correct HDMI input and the adapter's light is on."],
    },
    {
        "title": "If the correct TV / room name doesn't appear in the Connect list",
        "bullets": ['Go to Settings → Bluetooth & devices → Devices (or Cameras, mice, keyboards & other devices on older builds).', "Check the list of nearby devices for the room's display name.", "If it's listed, select it to connect from there.", 'If it isn\'t listed at all, select "Add device", choose "Wireless display or dock", and wait for it to appear, then pair.'],
    },
    {
        "title": "If the picture is laggy, drops out, or won't pair",
        "bullets": ['Disconnect and reconnect from the Connect panel.', "Unplug and replug the adapter's USB power lead to restart it (wait ~15 seconds), then try again.", 'For a fault that persists, log it as a repair job through the usual Ventia process (TVs/ICT are lodged as a repair and directed to the electrician for replacement).'],
    },
    {
        "title": "Updating the adapter's firmware",
        "bullets": ['Install the free "Microsoft Wireless Display Adapter" app from the Microsoft Store.', 'Open the app and connect to the adapter — similar to steps 2–3 above.', 'Once connected, select Firmware in the navigation pane on the left.', "If an update is available, follow the on-screen prompts. Don't unplug the adapter or close the app while it runs."],
    },
]


st.markdown(
    """
    <div style="background:linear-gradient(135deg,#16233F,#22345A);
                padding:22px 26px;border-radius:12px;margin-bottom:18px;">
        <div style="color:#6FD7CF;font-weight:700;font-size:13px;letter-spacing:0.5px;">
            CLC-LBU STAFF GUIDE
        </div>
        <div style="color:white;font-size:24px;font-weight:700;margin-top:4px;">
            Connecting Your PC to a Classroom TV
        </div>
        <div style="color:#C7D3E0;font-style:italic;font-size:14px;margin-top:2px;">
            Microsoft Wireless Display Adapter — quick reference
        </div>
    </div>
    """,
    unsafe_allow_html=True,
)

st.info(
    "**Before you start:** Wi-Fi must be on before pairing \u00b7 stay within ~7m (23ft) of the TV \u00b7 "
    "the adapter only takes one connection at a time \u00b7 each room's adapter is already plugged in and powered."
)

step_titles = [s["title"] for s in STEPS]
choice = st.selectbox("Jump to a step:", step_titles, index=0)
idx = step_titles.index(choice)
step = STEPS[idx]

col1, col2 = st.columns([1, 6])
with col1:
    if st.button("\u2190", disabled=(idx == 0), key="prev_step"):
        st.session_state["_step_idx"] = max(0, idx - 1)
        st.rerun()
with col2:
    if st.button("\u2192 Next step", disabled=(idx == len(STEPS) - 1), key="next_step"):
        st.session_state["_step_idx"] = min(len(STEPS) - 1, idx + 1)
        st.rerun()

st.subheader(step["title"])
st.image(img_bytes(step["img"]), use_container_width=True)
st.write(step["desc"])

st.markdown("---")
st.markdown("### \u26A0\ufe0f Troubleshooting & maintenance")
for item in TROUBLESHOOTING:
    with st.expander(item["title"]):
        for b in item["bullets"]:
            st.markdown(f"- {b}")

st.caption("CLC-LBU Reference Guide — Connecting a PC to a Classroom TV")
